22	/// `S-<shortname>` / `P-<shortname>` — the operator-facing label for a force.
23	pub(crate) fn force_label(force: &SnapshotForce) -> String {
24	    let prefix = match force.kind {
25	        ForceKind::Stressor => "S",
26	        ForceKind::Purpose => "P",
27	    };
28	    format!("{prefix}-{}", force.shortname)
29	}
