31	/// Bucket an open-ended status string into the small set of known lifecycle
32	/// stages the UI styles distinctly; anything else falls back to "other" but
33	/// keeps its raw text in the tooltip.
34	pub(crate) fn status_bucket(status: &str) -> &'static str {
35	    match status {
36	        "proposed" => "proposed",
37	        "actual" => "actual",
38	        "deprecated" => "deprecated",
39	        _ => "other",
40	    }
41	}
42	
43	pub(crate) fn status_tooltip(status: &str) -> String {
44	    match status {
45	        "proposed" => "proposed — staged in the ledger, not yet built".to_string(),
46	        "actual" => "actual — implemented and present in the codebase".to_string(),
47	        "deprecated" => "deprecated — superseded, scheduled for removal".to_string(),
48	        other => format!("{other} — non-standard status"),
49	    }
50	}
