52	pub(crate) fn row_total(force_id: &str, residues: &[SnapshotResidue]) -> usize {
53	    residues
54	        .iter()
55	        .filter(|r| r.force_id == force_id && r.coupled)
56	        .count()
57	}
58	
59	pub(crate) fn col_total(component: &str, residues: &[SnapshotResidue]) -> usize {
60	    residues
61	        .iter()
62	        .filter(|r| r.component_id == component && r.coupled)
63	        .count()
64	}
65	
66	pub(crate) fn architecture_sets_for_force(
67	    force_id: &str,
68	    components: &[SnapshotComponent],
69	    residues: &[SnapshotResidue],
70	) -> String {
71	    let mut sets: Vec<&str> = residues
72	        .iter()
73	        .filter(|r| r.force_id == force_id && r.coupled)
74	        .filter_map(|r| {
75	            components
76	                .iter()
77	                .find(|c| c.name == r.component_id)
78	                .map(|c| c.architecture_set.as_str())
79	        })
80	        .collect();
81	    sets.sort_unstable();
82	    sets.dedup();
83	    sets.join(" ")
84	}
