1	//! Static-export landscape rendering — replaces `src/view/html.rs`'s string
2	//! templating with Dioxus-rendered fragments spliced into the same template
3	//! shell. Red-phase scaffolding: the placeholder-substitution plumbing here
4	//! is real, but it delegates to `components::matrix`/`components::defense`,
5	//! which are `todo!()` stubs until the green phase.
6	//!
7	//! `TEMPLATE` is temporarily re-exported from `html.rs` since both files read
8	//! the same physical `template.html` asset during this transition; once
9	//! `html.rs` is deleted in the cutover phase, this file will own its own
10	//! `include_str!` (renamed `shell.html`).
11	
12	use anyhow::Result;
13	
14	use crate::view::components::defense::{render_defense_forms, render_defense_records};
15	use crate::view::components::matrix::render_matrix;
16	use crate::view::snapshot::LandscapeSnapshot;
17	
18	pub(crate) use super::html::TEMPLATE;
19	
20	/// Token in [`TEMPLATE`] replaced by the serialized snapshot.
21	pub const SNAPSHOT_PLACEHOLDER: &str = "{{SNAPSHOT_JSON}}";
22	
23	/// Element id of the `<script type="application/json">` block holding the snapshot.
24	pub const SNAPSHOT_ELEMENT_ID: &str = "residual-snapshot";
25	
26	const MATRIX_PLACEHOLDER: &str = "{{MATRIX}}";
27	const DEFENSE_FORMS_PLACEHOLDER: &str = "{{DEFENSE_FORMS}}";
28	const DEFENSE_RECORDS_PLACEHOLDER: &str = "{{DEFENSE_RECORDS}}";
29	
30	/// Render the full landscape page for a snapshot.
31	pub fn render_landscape_html(snapshot: &LandscapeSnapshot) -> Result<String> {
32	    let json = escape_script_json(&snapshot.to_json()?);
33	    let matrix = render_matrix(snapshot);
34	    let defense_records = match &snapshot.defense {
35	        Some(defense) => render_defense_records(defense),
36	        None => String::new(),
37	    };
38	    let defense_forms = match &snapshot.defense {
39	        Some(defense) => render_defense_forms(defense),
40	        None => String::new(),
41	    };
42	
43	    let html = TEMPLATE
44	        .replace(SNAPSHOT_PLACEHOLDER, &json)
45	        .replace(MATRIX_PLACEHOLDER, &matrix)
46	        .replace(DEFENSE_RECORDS_PLACEHOLDER, &defense_records)
47	        .replace(DEFENSE_FORMS_PLACEHOLDER, &defense_forms);
48	    Ok(html)
49	}
50	
51	/// Extract the embedded snapshot JSON from rendered HTML (round-trip helper).
52	pub fn extract_snapshot_json(html: &str) -> Option<&str> {
53	    let open = r#"<script id="residual-snapshot" type="application/json">"#;
54	    let start = html.find(open)? + open.len();
55	    let end = html[start..].find("</script>")? + start;
56	    Some(&html[start..end])
57	}
58	
59	/// Prevent ledger text from closing the embedding `<script>` block.
60	fn escape_script_json(json: &str) -> String {
61	    json.replace('<', "\\u003c")
62	}
