1	//! Self-contained landscape HTML — snapshot JSON embedded in a single file, no
2	//! network fetch, no build step. The page stages `residual add …` commands for
3	//! the operator to copy; it never mutates the ledger.
4	
5	use anyhow::Result;
6	
7	use crate::view::snapshot::{
8	    DefenseSection, ForceKind, LandscapeSnapshot, SnapshotAttractor, SnapshotComponent,
9	    SnapshotForce, SnapshotMetaForce, SnapshotResidue,
10	};
11	
12	/// The single-file page shell. Rendering substitutes [`SNAPSHOT_PLACEHOLDER`].
13	pub const TEMPLATE: &str = include_str!("template.html");
14	
15	/// Token in [`TEMPLATE`] replaced by the serialized snapshot.
16	pub const SNAPSHOT_PLACEHOLDER: &str = "{{SNAPSHOT_JSON}}";
17	
18	/// Element id of the `<script type="application/json">` block holding the snapshot.
19	pub const SNAPSHOT_ELEMENT_ID: &str = "residual-snapshot";
20	
21	const MATRIX_PLACEHOLDER: &str = "{{MATRIX}}";
22	const DEFENSE_FORMS_PLACEHOLDER: &str = "{{DEFENSE_FORMS}}";
23	const DEFENSE_RECORDS_PLACEHOLDER: &str = "{{DEFENSE_RECORDS}}";
24	
25	/// Render the full landscape page for a snapshot.
26	pub fn render_landscape_html(snapshot: &LandscapeSnapshot) -> Result<String> {
27	    let json = escape_script_json(&snapshot.to_json()?);
28	    let matrix = render_matrix(snapshot);
29	    let defense_records = match &snapshot.defense {
30	        Some(defense) => render_defense_records(defense),
31	        None => String::new(),
32	    };
33	    let defense_forms = match &snapshot.defense {
34	        Some(defense) => render_defense_forms(defense),
35	        None => String::new(),
36	    };
37	
38	    let html = TEMPLATE
39	        .replace(SNAPSHOT_PLACEHOLDER, &json)
40	        .replace(MATRIX_PLACEHOLDER, &matrix)
41	        .replace(DEFENSE_RECORDS_PLACEHOLDER, &defense_records)
42	        .replace(DEFENSE_FORMS_PLACEHOLDER, &defense_forms);
43	    Ok(html)
44	}
45	
46	/// Extract the embedded snapshot JSON from rendered HTML (round-trip helper).
47	pub fn extract_snapshot_json(html: &str) -> Option<&str> {
48	    let open = r#"<script id="residual-snapshot" type="application/json">"#;
49	    let start = html.find(open)? + open.len();
50	    let end = html[start..].find("</script>")? + start;
51	    Some(&html[start..end])
52	}
53	
54	/// Prevent ledger text from closing the embedding `<script>` block.
55	fn escape_script_json(json: &str) -> String {
56	    json.replace('<', r"\u003c")
57	}
58	
59	fn esc(value: &str) -> String {
60	    value
61	        .replace('&', "&amp;")
62	        .replace('<', "&lt;")
63	        .replace('>', "&gt;")
64	        .replace('"', "&quot;")
65	}
66	
67	fn force_kind_attr(kind: ForceKind) -> &'static str {
68	    match kind {
69	        ForceKind::Stressor => "stressor",
70	        ForceKind::Purpose => "purpose",
71	    }
72	}
73	
74	/// `S-<shortname>` / `P-<shortname>` — the operator-facing label for a force.
75	fn force_label(force: &SnapshotForce) -> String {
76	    let prefix = match force.kind {
77	        ForceKind::Stressor => "S",
78	        ForceKind::Purpose => "P",
79	    };
80	    format!("{prefix}-{}", force.shortname)
81	}
82	
83	/// Bucket an open-ended status string into the small set of known lifecycle
84	/// stages the UI styles distinctly; anything else falls back to "other" but
85	/// keeps its raw text in the tooltip.
86	fn status_bucket(status: &str) -> &'static str {
87	    match status {
88	        "proposed" => "proposed",
89	        "actual" => "actual",
90	        "deprecated" => "deprecated",
91	        _ => "other",
92	    }
93	}
94	
95	fn status_tooltip(status: &str) -> String {
96	    match status {
97	        "proposed" => "proposed — staged in the ledger, not yet built".to_string(),
98	        "actual" => "actual — implemented and present in the codebase".to_string(),
99	        "deprecated" => "deprecated — superseded, scheduled for removal".to_string(),
100	        other => format!("{other} — non-standard status"),
101	    }
102	}
103	
104	fn row_total(force_id: &str, residues: &[SnapshotResidue]) -> usize {
105	    residues
106	        .iter()
107	        .filter(|r| r.force_id == force_id && r.coupled)
108	        .count()
109	}
110	
111	fn col_total(component: &str, residues: &[SnapshotResidue]) -> usize {
112	    residues
113	        .iter()
114	        .filter(|r| r.component_id == component && r.coupled)
115	        .count()
116	}
117	
118	fn architecture_sets_for_force(
119	    force_id: &str,
120	    components: &[SnapshotComponent],
121	    residues: &[SnapshotResidue],
122	) -> String {
123	    let mut sets: Vec<&str> = residues
124	        .iter()
125	        .filter(|r| r.force_id == force_id && r.coupled)
126	        .filter_map(|r| {
127	            components
128	                .iter()
129	                .find(|c| c.name == r.component_id)
130	                .map(|c| c.architecture_set.as_str())
131	        })
132	        .collect();
133	    sets.sort_unstable();
134	    sets.dedup();
135	    sets.join(" ")
136	}
