138	/// Single unified table: sticky-left force column (accordion for full force
139	/// detail), sticky-top component header row (status dot + tooltip), sticky-
140	/// right row-totals column, sticky-bottom column-totals footer. Replaces the
141	/// old side-by-side force list + component chips + bare matrix.
142	fn render_matrix(snapshot: &LandscapeSnapshot) -> String {
143	    let forces: Vec<&SnapshotForce> = snapshot
144	        .stressors
145	        .iter()
146	        .chain(snapshot.purposes.iter())
147	        .collect();
148	
149	    let mut out = String::from(r#"<table class="matrix"><thead><tr>"#);
150	    out.push_str(
151	        r#"<th class="sticky-col sticky-row corner" data-sort-key="force" tabindex="0" role="button">force</th>"#,
152	    );
153	    for component in &snapshot.components {
154	        let bucket = status_bucket(&component.status);
155	        let tooltip = status_tooltip(&component.status);
156	        out.push_str(&format!(
157	            r#"<th class="sticky-row" data-component="{name}" data-status="{status}" data-architecture-set="{arch}" data-sort-key="component:{name}" title="{tooltip}" tabindex="0" role="button"><span class="status-dot status-{bucket}"></span>{name}</th>"#,
158	            name = esc(&component.name),
159	            status = esc(&component.status),
160	            arch = esc(&component.architecture_set),
161	            tooltip = esc(&tooltip),
162	            bucket = bucket,
163	        ));
164	    }
165	    out.push_str(
166	        r#"<th class="sticky-row sticky-col-right corner" data-sort-key="total">total</th>"#,
167	    );
168	    out.push_str("</tr></thead><tbody>");
169	
170	    for force in &forces {
171	        let kind = force_kind_attr(force.kind);
172	        let arch = architecture_sets_for_force(&force.id, &snapshot.components, &snapshot.residues);
173	        let search = format!(
174	            "{} {} {} {} {}",
175	            force.id, force.shortname, kind, force.attractor_id, arch
176	        );
177	        let label = force_label(force);
178	        let total = row_total(&force.id, &snapshot.residues);
179	        let attractor_label = snapshot
180	            .attractors
181	            .iter()
182	            .find(|a| a.id == force.attractor_id)
183	            .map(|a| format!("{} · {}", a.id, a.name))
184	            .unwrap_or_else(|| force.attractor_id.clone());
185	
186	        out.push_str(&format!(
187	            r#"<tr class="force-row" data-force-id="{id}" data-force-kind="{kind}" data-architecture-set="{arch}" data-attractor-id="{attractor_id}" data-search="{search}" data-row-total="{total}">"#,
188	            id = esc(&force.id),
189	            kind = kind,
190	            arch = esc(&arch),
191	            attractor_id = esc(&force.attractor_id),
192	            search = esc(&search),
193	            total = total,
194	        ));
195	        out.push_str(&format!(
196	            r#"<th class="sticky-col" data-force-id="{id}"><button type="button" class="force-accordion-toggle" data-accordion-toggle aria-expanded="false">{label}</button><div class="force-detail" hidden><dl><dt>id</dt><dd>{id}</dd><dt>attractor</dt><dd>{attractor}</dd><dt>description</dt><dd>{desc}</dd><dt>naive change</dt><dd>{naive}</dd><dt>outcomes</dt><dd>{outcomes}</dd></dl></div></th>"#,
197	            id = esc(&force.id),
198	            label = esc(&label),
199	            attractor = esc(&attractor_label),
200	            desc = esc(&force.description),
201	            naive = esc(&force.naive_change),
202	            outcomes = esc(&force.outcomes),
203	        ));
204	
205	        for component in &snapshot.components {
206	            let residue = snapshot
207	                .residues
208	                .iter()
209	                .find(|r| r.force_id == force.id && r.component_id == component.name);
210	            let coupled = residue.map(|r| r.coupled).unwrap_or(false);
211	            let coupled_attr = if coupled { "1" } else { "0" };
212	            let body = if coupled { "1" } else { "" };
213	            out.push_str(&format!(
214	                r#"<td data-residue-cell data-force-id="{force}" data-component="{comp}" data-coupled="{coupled}">{body}</td>"#,
215	                force = esc(&force.id),
216	                comp = esc(&component.name),
217	                coupled = coupled_attr,
218	                body = body,
219	            ));
220	        }
221	        out.push_str(&format!(
222	            r#"<td class="sticky-col-right" data-row-total="{total}">{total}</td>"#,
223	            total = total
224	        ));
225	        out.push_str("</tr>");
226	    }
227	    out.push_str("</tbody><tfoot><tr>");
228	    out.push_str(r#"<th class="sticky-col corner">totals</th>"#);
229	    let mut grand_total = 0usize;
230	    for component in &snapshot.components {
231	        let total = col_total(&component.name, &snapshot.residues);
232	        grand_total += total;
233	        out.push_str(&format!(
234	            r#"<td data-col-total="{total}" data-component="{name}">{total}</td>"#,
235	            total = total,
236	            name = esc(&component.name),
237	        ));
238	    }
239	    out.push_str(&format!(
240	        r#"<td class="sticky-col-right corner" data-grand-total="{gt}">{gt}</td>"#,
241	        gt = grand_total
242	    ));
243	    out.push_str("</tr></tfoot></table>");
244	    out
245	}
