247	fn render_defense_records(defense: &DefenseSection) -> String {
248	    let mut out = String::from(r#"<div class="defense-records"><h3>Defense</h3><ul>"#);
249	    for force in defense
250	        .meta_stressors
251	        .iter()
252	        .chain(defense.meta_purposes.iter())
253	    {
254	        out.push_str(&render_meta_force_item(force));
255	    }
256	    for attractor in &defense.meta_attractors {
257	        out.push_str(&render_meta_attractor_item(attractor));
258	    }
259	    for name in &defense.personas {
260	        out.push_str(&format!("<li>persona · {}</li>", esc(name)));
261	    }
262	    for name in &defense.strategies {
263	        out.push_str(&format!("<li>strategy · {}</li>", esc(name)));
264	    }
265	    for name in &defense.progress {
266	        out.push_str(&format!("<li>progress · {}</li>", esc(name)));
267	    }
268	    for name in &defense.pitches {
269	        out.push_str(&format!("<li>pitch · {}</li>", esc(name)));
270	    }
271	    out.push_str("</ul></div>");
272	    out
273	}
