1	//! Landscape view — read-only HTML rendering of the residual ledger.
2	//!
3	//! `residual view` writes a self-contained page to a temp dir (or `--out`) and
4	//! prints the path. `residual serve` hands the same page out over loopback.
5	//! Neither mutates the ledger: the page stages `residual add …` commands that
6	//! the operator copies and runs.
7	
8	pub mod commands;
9	pub mod components;
10	pub mod html;
11	pub mod snapshot;
12	pub mod static_export;
13	
14	use anyhow::{anyhow, Context, Result};
15	use std::path::PathBuf;
16	
17	use crate::config::Config;
18	
19	#[allow(unused_imports)] // re-exports for green agents / external callers
20	pub use commands::{format_add_command, format_add_commands, StagedAdd};
21	pub use html::render_landscape_html;
22	#[allow(unused_imports)] // re-exports for green agents / external callers
23	pub use snapshot::{
24	    load_landscape_snapshot, load_landscape_snapshot_from_dir, load_landscape_snapshot_from_sources,
25	    resolve_sources, LandscapeSnapshot, LandscapeSources,
26	};
27	
28	/// Filename written into the output directory.
29	pub const LANDSCAPE_FILENAME: &str = "landscape.html";
30	
31	/// Loopback host the landscape binds to. Never 0.0.0.0: the ledger is not public.
32	pub const SERVE_HOST: &str = "127.0.0.1";
33	
34	/// Default port for `residual serve` when `--port` is omitted.
35	pub const DEFAULT_PORT: u16 = 8787;
36	
37	#[derive(Debug, Clone, Default, PartialEq, Eq)]
38	pub struct ViewOptions {
39	    /// Include the defense ledger (meta forces + defense artifacts).
40	    pub include_defense: bool,
41	    /// Destination directory. `None` means the system temp dir (ephemeral, uncommitted).
42	    pub out_dir: Option<PathBuf>,
43	}
44	
45	/// What the server hands out: the page at `/`, the raw snapshot at `/snapshot.json`.
46	#[derive(Debug, Clone, PartialEq, Eq)]
47	pub struct ServeDocument {
48	    pub html: String,
49	    pub snapshot_json: String,
50	}
51	
52	/// Render the landscape and write it to disk. Returns the written HTML path.
53	pub fn write_landscape_html(cfg: &Config, opts: &ViewOptions) -> Result<PathBuf> {
54	    let snap = load_landscape_snapshot(cfg, opts.include_defense)?;
55	    let html = render_landscape_html(&snap)?;
56	
57	    let out_dir = match &opts.out_dir {
58	        Some(dir) => {
59	            std::fs::create_dir_all(dir)
60	                .with_context(|| format!("creating landscape out dir {}", dir.display()))?;
61	            dir.clone()
62	        }
63	        None => std::env::temp_dir(),
64	    };
65	
66	    let path = absolutize(out_dir.join(LANDSCAPE_FILENAME))?;
67	    std::fs::write(&path, html)
68	        .with_context(|| format!("writing landscape html to {}", path.display()))?;
69	    Ok(path)
70	}
71	
72	/// `residual view` entry point — writes the page and prints its path.
73	pub fn run_view(cfg: &Config, include_defense: bool, out_dir: Option<PathBuf>) -> Result<()> {
74	    let path = write_landscape_html(
75	        cfg,
76	        &ViewOptions {
77	            include_defense,
78	            out_dir,
79	        },
80	    )?;
81	    println!("{}", path.display());
82	    Ok(())
83	}
84	
85	/// Printable URL for a bound port.
86	pub fn serve_url(port: u16) -> String {
87	    format!("http://{SERVE_HOST}:{port}/")
88	}
89	
90	/// Build the served payload without binding a socket.
91	pub fn build_serve_document(cfg: &Config, include_defense: bool) -> Result<ServeDocument> {
92	    let snap = load_landscape_snapshot(cfg, include_defense)?;
93	    let html = render_landscape_html(&snap)?;
94	    let snapshot_json = snap.to_json()?;
95	    Ok(ServeDocument {
96	        html,
97	        snapshot_json,
98	    })
99	}
100	
101	/// Bind the loopback listener and block. Prints the URL before serving.
102	pub fn run_serve(cfg: &Config, include_defense: bool, port: u16) -> Result<()> {
103	    let doc = build_serve_document(cfg, include_defense)?;
104	    let url = serve_url(port);
105	    println!("{url}");
106	
107	    let addr = format!("{SERVE_HOST}:{port}");
108	    let server = tiny_http::Server::http(&addr)
109	        .map_err(|e| anyhow!("binding landscape server on {addr}: {e}"))?;
110	
111	    for request in server.incoming_requests() {
112	        let path = request.url().split('?').next().unwrap_or("/");
113	        let response = match path {
114	            "/" | "" => tiny_http::Response::from_data(doc.html.as_bytes())
115	                .with_header(content_type("text/html; charset=utf-8")),
116	            "/snapshot.json" => tiny_http::Response::from_data(doc.snapshot_json.as_bytes())
117	                .with_header(content_type("application/json; charset=utf-8")),
118	            _ => tiny_http::Response::from_string("not found")
119	                .with_status_code(404)
120	                .with_header(content_type("text/plain; charset=utf-8")),
121	        };
122	        // Keep serving even if a single client disconnects mid-write.
123	        let _ = request.respond(response);
124	    }
125	    Ok(())
126	}
127	
128	fn content_type(value: &str) -> tiny_http::Header {
129	    // Header values are ascii; the types we pass are literals.
130	    tiny_http::Header::from_bytes(&b"Content-Type"[..], value.as_bytes())
131	        .expect("Content-Type header is valid ascii")
132	}
133	
134	fn absolutize(path: PathBuf) -> Result<PathBuf> {
135	    if path.is_absolute() {
136	        Ok(path)
137	    } else {
138	        Ok(std::env::current_dir()
139	            .context("resolving current dir for landscape path")?
140	            .join(path))
141	    }
142	}
