194	                naive_change: &force.naive_change,
195	                outcomes: &force.outcomes,
196	                cells,
197	            }
198	        })
199	        .collect();
200	
201	    let footer_cols: Vec<FooterCol> = snapshot
202	        .components
203	        .iter()
204	        .map(|component| FooterCol {
205	            name: &component.name,
206	            total: col_total(&component.name, &snapshot.residues),
207	        })
208	        .collect();
209	    let grand_total: usize = footer_cols.iter().map(|c| c.total).sum();
210	
211	    let element = rsx! {
212	        table { class: "matrix",
213	            thead {
214	                tr {
215	                    th {
216	                        class: "sticky-col sticky-row corner",
217	                        "data-sort-key": "force",
