227	                            "data-architecture-set": "{col.architecture_set}",
228	                            "data-sort-key": "component:{col.name}",
229	                            title: "{col.tooltip}",
230	                            tabindex: "0",
231	                            role: "button",
232	                            span { class: "status-dot status-{col.bucket}" }
233	                            "{col.name}"
234	                        }
235	                    }
236	                    th {
237	                        class: "sticky-row sticky-col-right corner",
238	                        "data-sort-key": "total",
239	                        "total"
240	                    }
241	                }
242	            }
243	            tbody {
244	                for row in force_rows.iter() {
245	                    tr {
246	                        class: "force-row",
247	                        "data-force-id": "{row.id}",
248	                        "data-force-kind": "{row.kind}",
249	                        "data-architecture-set": "{row.arch}",
250	                        "data-attractor-id": "{row.attractor_id}",
251	                        "data-search": "{row.search}",
252	                        "data-row-total": "{row.total}",
253	                        th {
254	                            class: "sticky-col",
255	                            "data-force-id": "{row.id}",
256	                            button {
257	                                r#type: "button",
258	                                class: "force-accordion-toggle",
259	                                "data-accordion-toggle": "true",
260	                                "aria-expanded": "false",
261	                                "{row.label}"
262	                            }
263	                            div {
264	                                class: "force-detail",
265	                                hidden: "true",
266	                                dl {
267	                                    dt { "id" }
268	                                    dd { "{row.id}" }
269	                                    dt { "attractor" }
270	                                    dd { "{row.attractor_label}" }
271	                                    dt { "description" }
272	                                    dd { "{row.description}" }
273	                                    dt { "naive change" }
274	                                    dd { "{row.naive_change}" }
275	                                    dt { "outcomes" }
276	                                    dd { "{row.outcomes}" }
277	                                }
278	                            }
279	                        }
280	                        for cell in row.cells.iter() {
281	                            td {
282	                                "data-residue-cell": "true",
283	                                "data-force-id": "{row.id}",
284	                                "data-component": "{cell.component_name}",
285	                                "data-coupled": "{cell.coupled_attr}",
286	                                "{cell.body}"
287	                            }
288	                        }
289	                        td {
290	                            class: "sticky-col-right",
291	                            "data-row-total": "{row.total}",
292	                            "{row.total}"
293	                        }
294	                    }
295	                }
296	            }
297	            tfoot {
298	                tr {
299	                    th { class: "sticky-col corner", "totals" }
300	                    for col in footer_cols.iter() {
301	                        td {
302	                            "data-col-total": "{col.total}",
303	                            "data-component": "{col.name}",
304	                            "{col.total}"
305	                        }
306	                    }
307	                    td {
308	                        class: "sticky-col-right corner",
309	                        "data-grand-total": "{grand_total}",
310	                        "{grand_total}"
311	                    }
312	                }
313	            }
314	        }
315	    };
316	
317	    dioxus_ssr::render_element(element)
318	}
