1	//! Defense-section rendering — Dioxus-based implementation. Individual list
2	//! items are rendered through Dioxus (so escaping and markup stay consistent
3	//! with `matrix.rs`); the surrounding `<div>/<ul>` shell is assembled by
4	//! splicing those already-safe fragments in via `dangerous_inner_html`
5	//! (they were produced by our own renderer, not raw ledger text).
6	
7	use dioxus::prelude::*;
8	
9	use crate::view::snapshot::{DefenseSection, SnapshotAttractor, SnapshotMetaForce};
10	
11	pub fn render_defense_records(defense: &DefenseSection) -> String {
12	    let mut items = String::new();
13	    for force in defense.meta_stressors.iter().chain(defense.meta_purposes.iter()) {
14	        items.push_str(&render_meta_force_item(force));
15	    }
16	    for attractor in &defense.meta_attractors {
17	        items.push_str(&render_meta_attractor_item(attractor));
18	    }
19	    for name in &defense.personas {
20	        items.push_str(&render_labeled_item("persona", name));
21	    }
22	    for name in &defense.strategies {
23	        items.push_str(&render_labeled_item("strategy", name));
24	    }
25	    for name in &defense.progress {
26	        items.push_str(&render_labeled_item("progress", name));
27	    }
28	    for name in &defense.pitches {
29	        items.push_str(&render_labeled_item("pitch", name));
30	    }
31	
32	    dioxus_ssr::render_element(rsx! {
33	        div { class: "defense-records",
34	            h3 { "Defense" }
35	            ul { dangerous_inner_html: "{items}" }
36	        }
37	    })
38	}
39	
40	pub fn render_meta_force_item(force: &SnapshotMetaForce) -> String {
41	    dioxus_ssr::render_element(rsx! {
42	        li { "{force.id} · {force.shortname} — {force.description}" }
43	    })
44	}
45	
46	pub fn render_meta_attractor_item(attractor: &SnapshotAttractor) -> String {
47	    dioxus_ssr::render_element(rsx! {
48	        li { "{attractor.id} · {attractor.name} — {attractor.description}" }
49	    })
50	}
51	
52	/// Shared shape for the persona/strategy/progress/pitch list items, which
53	/// only differ by their label.
54	fn render_labeled_item(kind: &str, name: &str) -> String {
55	    dioxus_ssr::render_element(rsx! {
56	        li { "{kind} · {name}" }
57	    })
58	}
